  /* ---------- quiz first: new members answer the quiz, then make their account at the end ---------- */
  function startQuiz(fresh){
    if(fresh){lsDel(QUIZ_PENDING); /* "New here?" on a phone someone used before: start clean, nobody sees the last member's data */
      var old=[];try{for(var i=0;i<localStorage.length;i++){var k=localStorage.key(i);if(k&&(k.indexOf('nt:')===0||k.indexOf('nt-')===0))old.push(k)}}catch(e){}
      old.forEach(function(k){try{rawRemove.call(localStorage,k)}catch(e){}});[OWNER_KEY,DIRTY_KEY,'ntdataver','ntlastpull'].forEach(function(k){try{rawRemove.call(localStorage,k)}catch(e){}});dirty={};
      rawSet.call(localStorage,'ntguest','1');rawSet.call(localStorage,'ntgoquiz','1');reloadApp();return;
    }
    rawSet.call(localStorage,'ntguest','1');
    window.ntShowLogin=function(){try{localStorage.setItem('ntloginrequest','1')}catch(e){}reloadApp()};
    window.ntGoogle=googleStart;
    window.ntCreateAccount=createEmailAccount;
    startApp();
  }
  function showLogin(note){
    var root=document.getElementById('root');
    var mode='in';
    root.innerHTML='<style>'+css+'</style><form class="ntl" novalidate>'+
      '<h1 class="ntl-brand"><picture><source media="(min-width:640px)" srcset="'+NT_LOGO_LIGHT+'"><img src="'+NT_LOGO+'" alt="DropASize"></picture></h1><p id="ntl-sub"></p>'+
      '<div class="ntl-shell"><div class="ntl-core"><label for="ntl-e">Email</label><input id="ntl-e" type="email" autocomplete="email" autocapitalize="none">'+
      '<div id="ntl-pw"><label for="ntl-p">Password</label><input id="ntl-p" type="password" autocomplete="current-password"></div>'+
      '<button class="go" type="submit" id="ntl-go"></button>'+
      '<button class="lnk" type="button" id="ntl-sw"></button>'+
      '<div class="or" id="ntl-or">or</div><button class="ggl" type="button" id="ntl-g">'+G_ICON+'Continue with Google</button>'+
      '<div id="ntl-msg"></div></div></div>'+
      '<button class="lnk" type="button" id="ntl-fg">Forgot password?</button>'+
      '<p class="ntl-legal">By creating an account you agree to our <a href="'+PRIVACY_URL+'" target="_blank" rel="noopener">privacy policy</a>. DropASize gives general wellness information, not medical advice.</p></form>';
    var f=root.querySelector('form'),e=root.querySelector('#ntl-e'),p=root.querySelector('#ntl-p'),go=root.querySelector('#ntl-go'),sw=root.querySelector('#ntl-sw'),fg=root.querySelector('#ntl-fg'),msg=root.querySelector('#ntl-msg'),sub=root.querySelector('#ntl-sub'),pw=root.querySelector('#ntl-pw');
    function say(t,ok){msg.innerHTML=t?'<div class="msg '+(ok?'ok':'err')+'"></div>':'';if(t)msg.firstChild.textContent=t}
    function render(){
      sub.textContent=mode==='in'?'Welcome back. Log in to your coach.':mode==='up'?'Create your account. Your progress is saved safely online.':'Enter your email and we will send you a link to reset your password.';
      go.textContent=mode==='in'?'Log in':mode==='up'?'Create account':'Send reset link';
      sw.textContent=mode==='in'?'New here? Take the 60-second quiz':'I already have an account';
      pw.style.display=mode==='reset'?'none':'block';fg.style.display=mode==='in'?'block':'none';
      p.autocomplete=mode==='up'?'new-password':'current-password';
      gb.style.display=orl.style.display=mode==='reset'?'none':'';
    }
    var gb=root.querySelector('#ntl-g'),orl=root.querySelector('#ntl-or');
    gb.onclick=function(){say('');gb.disabled=true;googleStart();setTimeout(function(){gb.disabled=false},4000)};
    /* New members take the quiz first; the account is made at the end of it */
    sw.onclick=function(){if(mode==='in'){startQuiz(true);return}mode='in';say('');render()};
    fg.onclick=function(){mode='reset';say('');render()};
    f.onsubmit=async function(ev){
      ev.preventDefault();say('');
      var em=e.value.trim().toLowerCase(),pwd=p.value;
      if(em.indexOf('@')<1){say('Please enter a valid email address.');return}
      if(mode!=='reset'&&pwd.length<6){say('Password needs at least 6 characters.');return}
      go.disabled=true;var label=go.textContent;go.textContent='Please wait…';
      try{
        if(mode==='reset'){await authCall('recover?redirect_to='+encodeURIComponent(SITE_URL),{email:em});say('Done. Check your email for the reset link.',true)}
        else if(mode==='up'){
          var d=await authCall('signup',{email:em,password:pwd});
          if(d.access_token){saveSession(d);await enter(d.user,pwd);return}
          say('Almost there. We sent a link to '+em+'. Tap it to confirm your email, then come back and log in.',true);mode='in';render();
        }else{
          var s=await authCall('token?grant_type=password',{email:em,password:pwd});
          saveSession(s);await enter(s.user,pwd);return;
        }
      }catch(err){
        var m=String(err&&err.message||'');
        say(/invalid login/i.test(m)?'Wrong email or password.':/not confirmed/i.test(m)?'Please confirm your email first. Check your inbox for our link.':/already registered|already exists/i.test(m)?'This email already has an account. Log in instead.':/Failed to fetch|network/i.test(m)?'No internet connection. Check it and try again.':m);
      }
      go.disabled=false;go.textContent=label;
    };
    render();if(note)say(note);
  }


  /* Links from emails (confirm sign-up, reset password) land here with the login in the address. */
  function readEmailLink(){
    var h=location.hash.replace(/^#/,'');if(!h)return null;
    var p={};h.split('&').forEach(function(x){var i=x.indexOf('=');if(i>0)p[decodeURIComponent(x.slice(0,i))]=decodeURIComponent(x.slice(i+1).replace(/\+/g,' '))});
    if(!p.access_token&&!p.error&&!p.error_description)return null;
    try{history.replaceState(null,'',location.pathname+location.search)}catch(e){}
    return p;
  }
  async function userFor(tok){var r=await realFetch(SB_URL+'/auth/v1/user',{headers:{apikey:SB_KEY,Authorization:'Bearer '+tok}});if(!r.ok)throw new Error('That link has expired.');return r.json()}
  function showNewPassword(){
    var root=document.getElementById('root');
    root.innerHTML='<style>'+css+'</style><form class="ntl" novalidate><h1 class="ntl-brand"><picture><source media="(min-width:640px)" srcset="'+NT_LOGO_LIGHT+'"><img src="'+NT_LOGO+'" alt="DropASize"></picture></h1><p>Choose a new password for '+(session&&session.user?session.user.email.replace(/[<>&"]/g,''):'your account')+'.</p>'+
      '<div class="ntl-shell"><div class="ntl-core"><label for="ntl-n1">New password</label><input id="ntl-n1" type="password" autocomplete="new-password">'+
      '<label for="ntl-n2">Type it again</label><input id="ntl-n2" type="password" autocomplete="new-password">'+
      '<button class="go" type="submit" id="ntl-go">Save new password</button><div id="ntl-msg"></div></div></div></form>';
    var f=root.querySelector('form'),go=root.querySelector('#ntl-go'),msg=root.querySelector('#ntl-msg');
    function say(t,ok){msg.innerHTML='<div class="msg '+(ok?'ok':'err')+'"></div>';msg.firstChild.textContent=t}
    f.onsubmit=async function(ev){
      ev.preventDefault();var a=root.querySelector('#ntl-n1').value,b=root.querySelector('#ntl-n2').value;
      if(a.length<6){say('Password needs at least 6 characters.');return}
      if(a!==b){say('The two passwords don\u2019t match.');return}
      go.disabled=true;go.textContent='Saving…';
      try{
        var r=await realFetch(SB_URL+'/auth/v1/user',{method:'PUT',headers:{'Content-Type':'application/json',apikey:SB_KEY,Authorization:'Bearer '+(await token())},body:JSON.stringify({password:a})});
        if(!r.ok){var d={};try{d=await r.json()}catch(e){}throw new Error(/same/i.test(String(d.msg||d.message))?'Your new password must be different from the old one.':(d.msg||d.message||'Couldn\u2019t save your password.'))}
        say('Password saved. You can now log in with it in the app.',true);
        setTimeout(function(){enter(session.user,a)},1200);
      }catch(e){say(e.message);go.disabled=false;go.textContent='Save new password'}
    };
  }

